function csrfToken(){var t=document.querySelector('meta[name="csrf-token"]');return t?t.getAttribute("content"):""}document.addEventListener("click",(async function(t){const e=t.target.closest(".js-vote-btn");if(e){t.preventDefault();const o=e.closest(".toolStatsAjax");if(!o)return;const r=e.getAttribute("data-tool-id")||o.getAttribute("data-tool-id"),s=e.getAttribute("data-vote"),n=new URLSearchParams;n.set("id",r),n.set("type",s);try{const t=await fetch("/vote-tool-ajax.php",{method:"POST",headers:{"X-Requested-With":"XMLHttpRequest","X-CSRF-Token":csrfToken(),Accept:"application/json","Content-Type":"application/x-www-form-urlencoded; charset=UTF-8"},body:n.toString()}),r=await t.text();if(!t.ok)return console.error("Vote HTTP error:",t.status,r),void alert("Vote request failed");let s;try{s=JSON.parse(r)}catch(t){return console.error("Invalid JSON:",r),void alert("Invalid server response")}if(!s.success)return void alert(s.message||"Could not save vote");const c=o.querySelector(".js-like-count"),a=o.querySelector(".js-dislike-count"),i=o.querySelector(".js-click-count");c&&(c.textContent=s.likes??0),a&&(a.textContent=s.dislikes??0),i&&(i.textContent=s.clicks??0),o.querySelectorAll(".js-vote-btn").forEach((t=>t.classList.remove("active"))),e.classList.add("active")}catch(t){console.error(t),alert("Vote request failed")}}else;}));